


/** Renewal terms a subscription checkout commits the buyer to. Frozen when the session's order was created, so later plan changes do not alter them. */ export type CheckoutSubscriptionTermsInput = { "billing_interval": "daily" | "weekly" | "monthly" | "yearly"; /** Number of billing intervals between recurring charges. Format: int32. */ "billing_interval_count": number; /** Minimum commitment in months, when the plan has one. Format: int32. */ "contract_term_months"?: number; /** Fee charged when the buyer cancels before the contract term ends, when the plan has one. */ "early_termination_fee_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Flint subscription plan ID the terms come from. */ "plan_id": string; /** Plan name shown to the buyer. */ "plan_name": string; /** Charge for one billing interval before tax: each line's unit price times its quantity, plus modifiers. */ "recurring_total_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** One-time fee charged with the first payment, when the plan has one. */ "setup_fee_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Days before the first recurring charge, when the plan has a trial. Format: int32. */ "trial_period_days"?: number; };
